{
  "tools": [
    {
      "name": "load_cohort",
      "description": "Load a cohort CSV file, auto-detect static/dynamic mode, and return summary statistics (size, columns, date range, geographic coverage).",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Path to the CSV file"
          }
        },
        "required": [
          "path"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "plan_exposure",
      "description": "Return a no-download OpenAQ workload plan for the loaded static cohort. Call this before requesting researcher approval for an exposure run.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "country": {
            "type": "string",
            "description": "ISO alpha-2 country code (default: us)."
          },
          "n_stations": {
            "type": "integer",
            "minimum": 1
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ]
          },
          "location_strategy": {
            "type": "string",
            "enum": [
              "auto",
              "per_subject",
              "catalog"
            ]
          },
          "search_radius_km": {
            "type": "number",
            "exclusiveMinimum": 0,
            "maximum": 200
          }
        },
        "required": [
          "pollutant"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "estimate_exposure",
      "description": "Run exposure estimation for the loaded cohort. For static mode, specify a pollutant (pm25, pm10, no2, o3, so2, co, or 'all'). For dynamic mode, specify the backend (gmaps or xgb). Supports IDW multi-station averaging, outlier detection, and completeness QC for static mode.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "Pollutant to estimate (static mode). One of: pm25, pm10, no2, o3, so2, co, or 'all'"
          },
          "backend": {
            "type": "string",
            "description": "Dynamic mode backend: 'gmaps' (default) or 'xgb'",
            "enum": [
              "gmaps",
              "xgb"
            ]
          },
          "country": {
            "type": "string",
            "description": "ISO country code for geocoding (default: 'us')"
          },
          "n_stations": {
            "type": "integer",
            "description": "Number of stations for IDW averaging (default: 1, nearest only)"
          },
          "outlier_detection": {
            "type": "boolean",
            "description": "Enable IQR outlier removal before computing metrics (default: false)"
          },
          "min_completeness": {
            "type": "number",
            "description": "Minimum completeness percentage (0-100) for QC flagging"
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ],
            "description": "OpenAQ retrieval resolution. Use daily for daily health analyses to reduce API volume; hourly is retained for sub-daily analyses."
          },
          "location_strategy": {
            "type": "string",
            "enum": [
              "auto",
              "per_subject",
              "catalog"
            ],
            "description": "Station-discovery strategy. Auto can use a cached country catalog for large single-country cohorts and otherwise uses per-subject queries."
          },
          "search_radius_km": {
            "type": "number",
            "exclusiveMinimum": 0,
            "maximum": 200,
            "description": "Maximum city-to-monitor search distance in kilometres."
          },
          "approved_plan_id": {
            "type": "string",
            "description": "Immutable plan identifier approved by the researcher in interactive mode."
          }
        }
      },
      "requires_researcher_approval": true
    },
    {
      "name": "approve_exposure_plan",
      "description": "Bind explicit researcher approval to one immutable exposure plan.",
      "input_schema": {
        "type": "object",
        "properties": {
          "plan_id": {
            "type": "string"
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "plan_id",
          "researcher_approved"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "estimate_boundary_exposure",
      "description": "Estimate an ambient pollutant record for an explicit administrative boundary. Use either a researcher-supplied GeoJSON file or geoBoundaries ISO3/ADM selection. The result is an unweighted mean of monitor-level means within the polygon, with station coverage and boundary provenance.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "start_date": {
            "type": "string",
            "description": "Inclusive ISO date."
          },
          "end_date": {
            "type": "string",
            "description": "Inclusive ISO date."
          },
          "iso3": {
            "type": "string",
            "description": "ISO-3166 alpha-3 country code for geoBoundaries."
          },
          "adm_level": {
            "type": "integer",
            "minimum": 0,
            "maximum": 5
          },
          "boundary_name": {
            "type": "string",
            "description": "Administrative unit name or GeoJSON feature name."
          },
          "boundary_geojson_path": {
            "type": "string",
            "description": "Local GeoJSON path; preferred for a study-specific boundary."
          },
          "min_completeness": {
            "type": "number",
            "minimum": 0,
            "maximum": 100
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ],
            "description": "OpenAQ retrieval resolution. Use daily when the health outcome and intended analysis are daily."
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "pollutant",
          "start_date",
          "end_date"
        ]
      },
      "requires_researcher_approval": true
    },
    {
      "name": "estimate_boundary_exposure_batch",
      "description": "Estimate one pollutant for every selected feature in a boundary GeoJSON. Uses deterministic ordering, atomic per-unit checkpoints, and combined daily output. In self-driving mode, use deterministic chunks of at most 5 named boundaries.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "start_date": {
            "type": "string"
          },
          "end_date": {
            "type": "string"
          },
          "boundary_geojson_path": {
            "type": "string"
          },
          "boundary_names": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "min_completeness": {
            "type": "number",
            "minimum": 0,
            "maximum": 100
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ]
          },
          "checkpoint_path": {
            "type": "string"
          },
          "max_stations": {
            "type": "integer",
            "minimum": 1
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "pollutant",
          "start_date",
          "end_date",
          "boundary_geojson_path"
        ]
      },
      "requires_researcher_approval": true
    },
    {
      "name": "get_exposure_summary",
      "description": "Get summary statistics for the current exposure results: mean, SD, range, n with data, distance distribution.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "Which pollutant results to summarize (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_raw_data",
      "description": "Get raw hourly air quality measurements. A subject_id is required for point exposure and omitted for an administrative-boundary record.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "The subject identifier"
          },
          "pollutant": {
            "type": "string",
            "description": "Pollutant (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_daily_data",
      "description": "Get daily aggregated air quality data. A subject_id is required for point exposure and omitted for an administrative-boundary record.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "The subject identifier"
          },
          "pollutant": {
            "type": "string",
            "description": "Pollutant (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "compare_metrics",
      "description": "Compare exposure metrics (mean, median, p75, p95) across pollutants or between different estimation approaches.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutants": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "List of pollutants to compare (defaults to all available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "convert_to_aqi",
      "description": "Convert a pollutant concentration to EPA AQI value and category.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "One of: pm25, pm10, no2, o3, so2, co"
          },
          "concentration": {
            "type": "number",
            "description": "Concentration value to convert"
          }
        },
        "required": [
          "pollutant",
          "concentration"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_accuweather_air_quality",
      "description": "Retrieve AccuWeather's current/forecast air-quality index, category, and dominant-pollutant information for a coordinate. The response is a provider index and must not be used as a pollutant concentration.",
      "input_schema": {
        "type": "object",
        "properties": {
          "latitude": {
            "type": "number"
          },
          "longitude": {
            "type": "number"
          }
        },
        "required": [
          "latitude",
          "longitude"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "export_results",
      "description": "Export exposure results to a file. Supports CSV, GeoJSON, and long-format tidy CSV.",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Output file path"
          },
          "format": {
            "type": "string",
            "enum": [
              "csv",
              "geojson",
              "long_format"
            ],
            "description": "Export format (default: csv)"
          },
          "pollutant": {
            "type": "string",
            "description": "Which pollutant results to export (defaults to first available)"
          }
        },
        "required": [
          "path"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_station_info",
      "description": "Get monitoring station metadata for the exposure results. Static mode only.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "Optional: filter to a specific subject"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "web_search",
      "description": "Search the web for scientific literature, exposure guidelines, or methodological references.",
      "input_schema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query (e.g., 'PM2.5 childhood asthma epidemiology')"
          },
          "num_results": {
            "type": "integer",
            "description": "Number of results to return (default 5, max 10)"
          }
        },
        "required": [
          "query"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_decision_log",
      "description": "Return the current analytical decision log.",
      "input_schema": {
        "type": "object",
        "properties": {}
      },
      "requires_researcher_approval": false
    },
    {
      "name": "lock_reanalysis_invariants",
      "description": "Lock only the scientific invariants and safety bounds for a self-driving reanalysis; leave retrieval and implementation choices open.",
      "input_schema": {
        "type": "object",
        "properties": {
          "study_id": {
            "type": "string"
          },
          "research_question": {
            "type": "string"
          },
          "target_outcome_and_population": {
            "type": "string"
          },
          "pollutants": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "principal_contrast": {
            "type": "string"
          },
          "principal_variants": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string"
            },
            "description": "The explicit fitted comparison selected as the reanalysis target. Ordinarily provide one label anchored to a table, figure, model, or results sentence. Include another variant only when it forms part of the same prespecified target and will receive its own fitted result."
          },
          "broad_geography": {
            "type": "string"
          },
          "target_geographic_units": {
            "type": [
              "integer",
              "null"
            ],
            "minimum": 1,
            "description": "Article-reported count of geographic units, when stated. Leave null when the article gives no count."
          },
          "target_geographic_unit_type": {
            "type": [
              "string",
              "null"
            ],
            "description": "Article-reported unit type, such as county or municipality."
          },
          "start_date": {
            "type": "string"
          },
          "end_date": {
            "type": "string"
          },
          "prohibited_evidence": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "article_evidence": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "artifact": {
                  "type": "string",
                  "description": "Saved article or supplement path."
                },
                "finding": {
                  "type": "string",
                  "description": "Scientific specification supported by the artifact."
                }
              },
              "required": [
                "artifact",
                "finding"
              ],
              "additionalProperties": false
            }
          },
          "article_evidence_map": {
            "type": "object",
            "description": "Optional structured notes from article inspection. This is evidence, not a compliance checklist, and may be partial when full text is unavailable."
          }
        },
        "required": [
          "study_id",
          "research_question",
          "target_outcome_and_population",
          "pollutants",
          "principal_contrast",
          "principal_variants",
          "broad_geography",
          "start_date",
          "end_date",
          "prohibited_evidence",
          "article_evidence"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "update_research_notebook",
      "description": "Persist restart-safe research state: evidence, decisions, blockers, and next actions.",
      "input_schema": {
        "type": "object",
        "properties": {
          "phase": {
            "type": "string",
            "enum": [
              "specify",
              "recover",
              "fit",
              "audit",
              "complete"
            ]
          },
          "objective": {
            "type": "string"
          },
          "invariants": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "evidence": {
            "type": "array",
            "items": {
              "type": "object"
            }
          },
          "hypotheses": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "routes_attempted": {
            "type": "array",
            "items": {
              "type": "object"
            }
          },
          "decisions": {
            "type": "array",
            "items": {
              "type": "object"
            }
          },
          "unresolved_blockers": {
            "type": "array",
            "items": {
              "type": "object"
            }
          },
          "next_actions": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "phase",
          "objective",
          "invariants",
          "evidence",
          "hypotheses",
          "routes_attempted",
          "decisions",
          "unresolved_blockers",
          "next_actions"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "amend_exposure_contract",
      "description": "Append an evidence-backed execution amendment without rewriting prior contracts. In the reanalysis profile, call this after feasibility probes to record the executable exposure design before full retrieval or finalization. The first amendment's changed_dimensions must contain the complete design: geographic_representation, assignment_method, source_strategy, exposure_metric, daily_aggregation, analysis_aggregation, coverage_policy, and intended_use. Cite the returned contract_path in the final result.",
      "input_schema": {
        "type": "object",
        "properties": {
          "changed_dimensions": {
            "type": "object",
            "description": "On the first amendment, include the executable exposure fields. Later amendments contain only evidence-backed dimensions that changed."
          },
          "evidence": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "artifact": {
                  "type": "string"
                },
                "finding": {
                  "type": "string"
                }
              },
              "required": [
                "artifact",
                "finding"
              ],
              "additionalProperties": false
            }
          },
          "scientific_justification": {
            "type": "string"
          },
          "fidelity_impact": {
            "type": "string",
            "enum": [
              "none",
              "source_substitution",
              "coverage_subset",
              "covariate_omission",
              "construct_change",
              "supported_sensitivity"
            ]
          },
          "agreement_independent": {
            "type": "boolean"
          }
        },
        "required": [
          "changed_dimensions",
          "evidence",
          "scientific_justification",
          "fidelity_impact",
          "agreement_independent"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "record_reanalysis_fidelity",
      "description": "Persist the fidelity class, deviations, and evidence for a completed or stopped reanalysis.",
      "input_schema": {
        "type": "object",
        "properties": {
          "study_id": {
            "type": "string"
          },
          "fidelity_class": {
            "type": "string",
            "enum": [
              "matched_fit",
              "source_substitution_fit",
              "reduced_coverage_fit",
              "reduced_adjustment_fit",
              "bounded_fit",
              "supported_sensitivity_fit",
              "bounded_proxy_fit",
              "unsupported_fit",
              "evidenced_stop"
            ]
          },
          "status": {
            "type": "string",
            "enum": [
              "fitted",
              "stopped"
            ]
          },
          "preserved_dimensions": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "deviations": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "dimension": {
                  "type": "string"
                },
                "change_type": {
                  "type": "string",
                  "enum": [
                    "source",
                    "coverage_subset",
                    "covariate_omission",
                    "construct_change"
                  ]
                },
                "published": {
                  "type": "string"
                },
                "reanalysis": {
                  "type": "string"
                },
                "reason": {
                  "type": "string"
                }
              },
              "required": [
                "dimension",
                "change_type"
              ]
            }
          },
          "evidence_artifacts": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "reported_variants": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "recovery_checklist": {
            "type": "object",
            "description": "For bounded or construct-changing fits, include author_repository_applicable, author_repository_attempted, and author_repository_evidence. The evidence value must name a saved artifact. Stopped runs also require the complete recovery checklist. The stop checklist must state whether an article-named regulator applies, preserve evidence, inspect the portal interface, and attempt at least three distinct public recovery routes. It must also preserve at least two discovery searches, follow plausible results, and inspect a public client or source implementation when one exists. If an official bulk endpoint failed, it must also preserve an exact-file mirror search. Search results and applicable public clients must be inspected, not merely listed. It must list concrete stop_counterexamples_tested and saved stop_counterexample_evidence.",
            "properties": {
              "executable_attempts": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "request_url": {
                      "type": "string"
                    },
                    "command": {
                      "type": "string"
                    },
                    "source_role": {
                      "type": "string",
                      "enum": [
                        "outcome",
                        "exposure",
                        "covariate",
                        "article"
                      ]
                    },
                    "response_status": {},
                    "captured_error": {
                      "type": "string"
                    },
                    "bytes_returned": {
                      "type": "integer"
                    },
                    "records_returned": {
                      "type": "integer"
                    },
                    "schema_or_format_inspection": {
                      "type": "string"
                    },
                    "evidence_artifact": {
                      "type": "string"
                    },
                    "attempt_count": {
                      "type": "integer",
                      "minimum": 1
                    }
                  },
                  "required": [
                    "source_role",
                    "schema_or_format_inspection",
                    "evidence_artifact",
                    "attempt_count"
                  ]
                }
              },
              "target_specification_complete": {
                "type": "boolean"
              },
              "complete_article_checked": {
                "type": "boolean"
              },
              "outcome_routes_attempted": {
                "type": "integer",
                "minimum": 0
              },
              "normal_exposure_source_tested": {
                "type": "boolean"
              },
              "historical_fallback_applicable": {
                "type": "boolean"
              },
              "historical_fallback_tested": {
                "type": "boolean"
              },
              "article_named_regulator_applicable": {
                "type": "boolean"
              },
              "article_named_regulator_attempted": {
                "type": "boolean"
              },
              "article_named_regulator_evidence": {
                "type": "string"
              },
              "article_named_regulator_interface_inspected": {
                "type": "boolean"
              },
              "article_named_regulator_routes_attempted": {
                "type": "integer",
                "minimum": 0
              },
              "article_named_regulator_search_queries": {
                "type": "integer",
                "minimum": 0
              },
              "article_named_regulator_search_evidence": {
                "type": "string"
              },
              "article_named_regulator_results_followed": {
                "type": "boolean"
              },
              "article_named_regulator_public_client_inspected": {
                "type": "boolean"
              },
              "article_named_regulator_client_evidence": {
                "type": "string"
              },
              "article_named_regulator_applicability_evidence": {
                "type": "string"
              },
              "official_bulk_endpoint_failed": {
                "type": "boolean"
              },
              "bulk_public_client_inspected": {
                "type": "boolean"
              },
              "bulk_public_client_evidence": {
                "type": "string"
              },
              "exact_file_mirror_search_attempted": {
                "type": "boolean"
              },
              "exact_file_mirror_search_evidence": {
                "type": "string"
              },
              "exact_file_mirror_route_types": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "exact_file_search_results_followed": {
                "type": "boolean"
              },
              "geographic_batching_applicable": {
                "type": "boolean"
              },
              "geographic_batching_attempted": {
                "type": "boolean"
              },
